      pose proof ctx_facts as (X1 & [X2 X2'] & X3 & X4 & X5 & X6 & X7 & X8 & X9 & X10 & X11 & TP & FRM & EHS); pose proof USPW as U;
      pose proof (bv_unsigned_in_range _ sp) as RSP; unfold bv_modulus in RSP; cbn in RSP;
      pose proof (bv_unsigned_in_range _ a0) as RA0; unfold bv_modulus in RA0; cbn in RA0; hcb.
    (* [comment removed for export] *)
    Ltac segW := unfold segW_ok; repeat (apply Forall_cons; [cbn [fst snd]; unfold pa, ta in *; lia|]); apply Forall_nil.
    Ltac dj := cbn [disjoint_from fst snd]; unfold pa, ta in *; lia.
    (* [comment removed for export] *)
    Ltac join_scratch m' :=
      try (lazymatch goal with
           | Hs : rw_cells rsegs m' (bv_unsigned a0 + 160) (CB 8 _ :: _) |- _ =>
               let sc' := fresh "sc'" in let J := fresh "SCRJ" in destruct (scratch_join m' _ _ Hs eq_refl) as [sc' J]
           end).
    (* [comment removed for export] *)
    Ltac rebuild_memI MI BUF :=
      lazymatch goal with |- memI ?m2 _ _ _ _ _ _ _ => join_scratch m2 end;
      eapply memI_seg;
      [ exact MI | eassumption | eassumption | eassumption
      | first [ eassumption | match goal with Hst : stk _ _ _ (bv_unsigned spw) |- _ => eapply stk_transport_disjoint; [exact Hst| eassumption| eassumption| dj] end ] | segW
      | unfold uframe; lazymatch goal with |- rw_cells _ ?mm ?A _ => match goal with Hf : rw_cells _ mm A _ |- _ => exact Hf end end
      | unfold usize; eassumption | eassumption | eassumption
      | first [ eapply buf_keep; [exact BUF| eassumption| eassumption| dj]
              | eapply buf_put1; [exact BUF| eassumption| lia| lia| eassumption| eassumption| dj| dj]
