    Ltac go_msusp KR MP MI BUF PSI Rgp Rtp :=
      eapply tail_msusp; [ | exact KR| exact MP| first [exact MI| rebuild_memI MI BUF]| exact PSI| unfold vs_n in *; lia| reg_sp| reg_via Rgp| reg_via Rtp| eassumption
        | eassumption| unfold q0 in *; lia| eassumption]; first [left; reflexivity| right; left; reflexivity| right; right; reflexivity].
    Ltac go_fail KR MP MI BUF PSI Rgp Rtp :=
      first [ eapply tail_failE; [exact KR| exact MP| first [exact MI| rebuild_memI MI BUF]| exact PSI| unfold vs_n in *; lia| reg_sp| reg_via Rgp| reg_via Rtp| eassumption
                | eassumption| unfold q0 in *; lia| eassumption| lia| eassumption| lia| eassumption]
            | eapply tail_failB; [exact KR| exact MP| first [exact MI| rebuild_memI MI BUF]| exact PSI| unfold vs_n in *; lia| reg_sp| reg_via Rgp| reg_via Rtp| eassumption
                | eassumption| eassumption| unfold q0 in *; lia| lia| eassumption| lia| eassumption| lia| eassumption]
            | eapply tail_failK; [exact KR| exact MP| first [exact MI| rebuild_memI MI BUF]| exact PSI| unfold vs_n in *; lia| reg_sp| reg_via Rgp| reg_via Rtp| eassumption
                | eassumption| unfold q0 in *; lia| eassumption| eassumption| lia| eassumption] ].
    Ltac solve1 Rgp Rtp :=
      first [ eassumption | reg_via Rgp | reg_via Rtp | eapply ucore_sp; eassumption | reflexivity | unfold q0, vs_n in *; lia ].
    Ltac go_next KX KR MP MI BUF PSI Rgp Rtp :=
      eapply KX; [exact KR| exact MP| first [exact MI| rebuild_memI MI BUF]| exact PSI| solve1 Rgp Rtp ..].

