    (* [comment removed for export] *)
    (* [comment removed for export] *)
    Ltac seg_hyps := first [ exact UCTX | eassumption | exact ISK | unfold q0, vs_n in *; lia ].
    Ltac ucore_rv := lazymatch goal with Hc : ucore ?r0 _ _ |- ucore _ _ _ => first [exact Hc | unfold ucore in Hc |- *; rv_cbv; exact Hc] end.
    (* [comment removed for export] *)
    Ltac utf8_then_loopend KL q' KR MP PSI Rgp Rtp :=
      intros m2 a1' a2' a3' a4' a5' kk KB MI2;
      eapply (KL q' ltac:(lia)); [exact KR| exact MP| exact MI2| exact PSI| ucore_rv| rv_cbv; reg_via Rgp| rv_cbv; reg_via Rtp| rv_cbv; eassumption
        | unfold q0 in *; lia| lia| lia| lia| lia| unfold vs_n in *; lia].

    (* [comment removed for export] *)
    Ltac cut_prep MI PSI q :=
      prep; open_memI MI;
      let PSI' := fresh "PSI'" in pose proof PSI as PSI'; destruct PSI' as (PE & PD & PEC & PM & PIT & PTM & PCH & TNN);
      lazymatch goal with PAx : parser_at _ _ _, INx : bytes_at _ _ p0 ibs |- _ =>
        destruct (ucells_of _ _ _ PAx PSI) as (sc & u1w & u2w & pad7 & v1 & v2 & v3 & PCL);
        pose proof (pinput_of _ q INx ltac:(unfold q0 in *; lia)) as INB end.
    Ltac seg_leaves := let LV := fresh "LV" in intros ms' (pc' & r' & m' & -> & LV); repeat (lazymatch type of LV with _ \/ _ => destruct LV as [LV|LV] end); leaf LV pc' m'.

